// Golden test for the link maths: numbers generated by the website's own mesh.ts / profile.ts / coverage.ts functions
// (meshcore-insights scripts/plan-tools-golden.ts -> test/fixtures/plan_tools_golden.json).
import 'package:flutter_test/flutter_test.dart';
import 'package:meshsonar/core/plan/link_model.dart';

import 'plan_golden.dart';

double _d(Object? v) => (v as num).toDouble();

void main() {
  final g = loadPlanGolden()['link'] as Map<String, dynamic>;
  final profiles = {for (final p in (g['profiles'] as List).cast<Map<String, dynamic>>()) p['name'] as String: p};

  test('constants agree with the website', () {
    expect(lambdaM, closeTo(_d(g['lambdaM']), 1e-12));
    expect(keM, closeTo(_d(g['keM']), 1e-6));
    expect(sensitivityDbmLink(), closeTo(_d(g['sensitivityDbm']), 1e-12));
    expect(noiseFloorDbm(), closeTo(_d(g['noiseFloorDbm']), 1e-12));
    final t = g['tiers'] as Map<String, dynamic>;
    expect([terrainTiers.strong, terrainTiers.likely, terrainTiers.possible], [t['strong'], t['likely'], t['possible']]);
  });

  test('haversine and the odds grid match', () {
    for (final h in (g['haversine'] as List).cast<Map<String, dynamic>>()) {
      expect(haversineKm(_d(h['a']), _d(h['b']), _d(h['c']), _d(h['d'])), closeTo(_d(h['km']), 1e-9));
    }
    for (final o in (g['oddsGrid'] as List).cast<Map<String, dynamic>>()) {
      expect(terrainOdds(_d(o['km']), _d(o['bull'])), closeTo(_d(o['odds']), 1e-12));
    }
  });

  test('every profile x antenna height: Bullington, odds, tier, Fresnel clearance and the painter budget match', () {
    final links = (g['links'] as List).cast<Map<String, dynamic>>();
    expect(links.length, 12);
    for (final l in links) {
      final p = profiles[l['profile']]!;
      final ground = [for (final v in p['ground'] as List) _d(v)];
      final a = analyseLink(ground, _d(p['km']), _d(l['haM']), _d(l['hbM']));
      final tag = '${l['profile']} ${l['haM']}/${l['hbM']} m';
      expect(a.bullDb, closeTo(_d(l['bullDb']), 1e-9), reason: tag);
      expect(a.odds, closeTo(_d(l['odds']), 1e-12), reason: tag);
      expect(a.tier.label, l['tier'], reason: tag);
      final c = l['clearance'] as Map<String, dynamic>;
      expect(a.clear.worstRatio, closeTo(_d(c['worstRatio']), 1e-9), reason: tag);
      expect(a.clear.worstKm, closeTo(_d(c['worstKm']), 1e-9), reason: tag);
      expect(a.clear.worstClearM, closeTo(_d(c['worstClearM']), 1e-9), reason: tag);
      expect(a.clear.clearShare, closeTo(_d(c['clearShare']), 1e-12), reason: tag);
      expect(a.clear.blockedM, c['blockedM'], reason: tag);
      expect(a.clear.bullDb, closeTo(_d(c['bullDb']), 1e-9), reason: tag);
      final m = l['p2p'] as Map<String, dynamic>;
      expect(a.fspl, closeTo(_d(m['fsplDb']), 1e-9), reason: tag);
      expect(a.diffractionDb, closeTo(_d(m['bullLossDb']), 1e-9), reason: tag);
      expect(a.los, m['los'], reason: tag);
      expect(a.clutterDb, closeTo(_d(m['clutterDb']), 1e-9), reason: tag);
      expect(a.pathLossDb, closeTo(_d(m['pathLossDb']), 1e-9), reason: tag);
      expect(a.marginDb, closeTo(_d(m['marginDb']), 1e-9), reason: tag);
      expect(a.prxDbm, closeTo(_d(m['prxDbm']), 1e-9), reason: tag);
    }
  });

  test('the fixtures really exercise both a blocked and a clear path', () {
    final links = (g['links'] as List).cast<Map<String, dynamic>>();
    expect(links.any((l) => (l['clearance'] as Map)['blockedM'] > 0), isTrue);
    expect(links.any((l) => (l['clearance'] as Map)['blockedM'] == 0), isTrue);
    expect(links.map((l) => l['tier']).toSet().length, greaterThan(1));
  });
}
